const envelope     = $input.first().json;
const tz           = envelope.tenant?.timezone ?? 'America/Mexico_City';
const session      = envelope.session ?? {};
const pending      = session.pending_context ?? {};
const eventTypeId  =
  pending.calcom_event_type_id ??
  envelope._selected_provider?.calcom_event_type_id ??
  envelope.tenant?.settings?.calcom_event_type_id ??
  null;
const serviceId    = session.active_service_id ?? pending.active_service_id ?? null;
const providerId   = session.active_provider_id ?? pending.active_provider_id ?? pending.provider_id ?? null;
const patientId    = session.active_patient_id ?? envelope.patient?.active_patient_id ?? null;
const bookingUidToReschedule = pending.reschedule_uid ?? null;

let error = null;
if (!eventTypeId) error = 'missing_calcom_event_type_id';
else if (!serviceId) error = 'missing_service_id';
else if (!patientId) error = 'missing_patient_id';

const now   = new Date();
const start = now.toISOString();
const end   = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString();

const hasCachedSlots = !error &&
  Array.isArray(pending.available_slots) &&
  pending.available_slots.length > 0;
const tryNlpSlot = false;

return [{
  json: {
    ...envelope,
    _error: error,
    _calcom_event_type_id: eventTypeId,
    _service_id:  serviceId,
    _provider_id: providerId,
    _provider_name: pending.provider_name ?? null,
    _provider_specialty: pending.provider_specialty ?? null,
    _patient_id:  patientId,
    _slot_start:  start,
    _slot_end:    end,
    _timezone:    tz,
    _booking_uid_to_reschedule: bookingUidToReschedule,
    _has_cached_slots: hasCachedSlots,
    _try_nlp_slot:     tryNlpSlot
  }
}];

// ── CF-11 · Procesar slots — agrupado por día, copy humanizado ────────────
const envelope = $('Preparar ventana').item.json;
const raw      = $input.first().json;

// Si vino de Enrich Meta, leer de ahí
let calResp = raw;
if (raw._calcom_response) {
  calResp = raw._calcom_response;
}

const session     = envelope.session ?? {};
const pending     = session.pending_context ?? {};
const tz          = envelope.tenant?.timezone ?? 'America/Mexico_City';
const patientName = raw._patient_name ?? null;
const serviceName = raw._service_name ?? null;
const serviceDur  = raw._service_duration ?? null;
const providerName = raw._provider_name ?? envelope._provider_name ?? null;

const invalidSelection = envelope._slot_selection_invalid === true;

// ── Helper: formatear fecha ────────────────────────────────────────────────
const fmt = (iso, opts) => {
  try {
    return new Intl.DateTimeFormat('es-MX', { timeZone: tz, ...opts }).format(new Date(iso));
  } catch { return iso; }
};

const fmtHour = (iso) => fmt(iso, { hour: '2-digit', minute: '2-digit', hour12: true });
const fmtDay  = (iso) => fmt(iso, { weekday: 'long', day: 'numeric', month: 'long' });
const fmtDayShort = (iso) => fmt(iso, { weekday: 'short', day: 'numeric', month: 'short' });

const buildNoSlots = (body) => [{
  json: {
    ...envelope,
    _patient_name: patientName,
    _service_name: serviceName,
    session: { ...session, current_step: 'select_slot',
               pending_context: { ...pending, available_slots: [] } },
    _session_update: { current_step: 'select_slot',
                       pending_context: { ...pending, available_slots: [] } },
    _outbound: { type: 'text', body }
  }
}];

if (calResp?.status !== 'success' || !calResp?.data) {
  return buildNoSlots('😔 No encontré disponibilidad en los próximos 30 días.\n\nEscribe *hola* para volver al menú.');
}

// ── Recopilar y deduplicar todos los slots ────────────────────────────────
const allSlots = [];
for (const [date, slots] of Object.entries(calResp.data)) {
  for (const slot of (Array.isArray(slots) ? slots : [])) {
    if (slot?.start) allSlots.push({ date, start: slot.start, end: slot.end ?? null });
  }
}
allSlots.sort((a, b) => new Date(a.start) - new Date(b.start));

const seen  = new Set();
const dedup = allSlots.filter(s => {
  const k = s.start;
  if (seen.has(k)) return false;
  seen.add(k); return true;
});

if (dedup.length === 0) {
  return buildNoSlots('😔 No hay horarios disponibles en los próximos 30 días.\n\nEscribe *hola* para volver al menú.');
}

// ── Tomar varios días disponibles, respetando lo que Cal.com devuelve ─────
const MAX_DAYS_TO_SHOW = 5;
const MAX_SLOTS_PER_DAY = 5;
const MAX_TOTAL_SLOTS = 25;

const byDayAll = {};
for (const slot of dedup) {
  const dayKey = slot.date || slot.start.slice(0, 10);
  if (!byDayAll[dayKey]) byDayAll[dayKey] = [];
  byDayAll[dayKey].push(slot);
}

const selectedDays = Object.keys(byDayAll)
  .sort()
  .slice(0, MAX_DAYS_TO_SHOW);

const topSlots = [];
const byDay = {};
for (const day of selectedDays) {
  const slotsForDay = byDayAll[day].slice(0, MAX_SLOTS_PER_DAY);
  byDay[day] = [];
  for (const slot of slotsForDay) {
    if (topSlots.length >= MAX_TOTAL_SLOTS) break;
    topSlots.push(slot);
    byDay[day].push(slot);
  }
}

for (const day of Object.keys(byDay)) {
  if (byDay[day].length === 0) delete byDay[day];
}

// ── Construir texto agrupado ───────────────────────────────────────────────
let slotIndex = 0;
let catalogLines = [];
const days = Object.keys(byDay).sort();

for (const day of days) {
  const slots = byDay[day];
  const dayLabel = fmtDay(slots[0].start);
  // Capitalizar primera letra
  const dayLabelCap = dayLabel.charAt(0).toUpperCase() + dayLabel.slice(1);

  // Destacar el primero de todos como "más cercano"
  const isFirstDay = day === days[0];
  const dayHeader = isFirstDay
    ? `📍 *${dayLabelCap}* _(más cercano)_`
    : `📅 *${dayLabelCap}*`;

  catalogLines.push(dayHeader);

  for (const slot of slots) {
    slotIndex++;
    const hour = fmtHour(slot.start);
    catalogLines.push(`   ${slotIndex}. ${hour}`);
  }
  catalogLines.push(''); // línea vacía entre días
}

// Quitar última línea vacía
if (catalogLines[catalogLines.length - 1] === '') catalogLines.pop();
const catalogText = catalogLines.join('\n');

// ── Construir intro personalizada ─────────────────────────────────────────
let intro = '';
if (invalidSelection) {
  intro = '⚠️ No pude identificar el número de horario que elegiste. Aquí están las opciones de nuevo:\n\n';
} else if (patientName && serviceName) {
  intro = `Aquí están los horarios disponibles para *${serviceName}*${serviceDur ? ` (${serviceDur} min)` : ''}, para la cita de *${patientName}*${providerName ? ` con *${providerName}*` : ''}:\n\n`;
} else if (serviceName) {
  intro = `Aquí están los horarios disponibles para *${serviceName}*:\n\n`;
} else {
  intro = 'Aquí están los próximos horarios disponibles:\n\n';
}

const body =
  intro +
  catalogText +
  `\n\n_Responde solo con el número del horario que prefieras._`;

// ── Guardar slots en pending_context para CF-06 y CF-12 ───────────────────
const pendingContext = {
  ...pending,
  queried_at:      new Date().toISOString(),
  available_slots: topSlots,
  patient_name:    patientName,
  service_name:    serviceName,
  provider_id:     envelope._provider_id ?? pending.provider_id ?? null,
  provider_name:   providerName,
  calcom_event_type_id: envelope._calcom_event_type_id ?? pending.calcom_event_type_id ?? null,
};

return [{
  json: {
    ...envelope,
    _patient_name: patientName,
    _service_name: serviceName,
    session: { ...session, current_step: 'awaiting_slot_selection',
               pending_context: pendingContext },
    _session_update: { current_step: 'awaiting_slot_selection',
                       pending_context: pendingContext },
    _outbound: { type: 'text', body }
  }
}];

const e = $input.first().json;
const msgs = {
  missing_calcom_event_type_id: '⚠️ Esta clínica o médico no tiene configurada su agenda todavía.\nContáctanos directamente para agendar.',
  missing_service_id: '⚠️ Primero necesito que elijas un servicio.\n\nEscribe *hola* para reiniciar.',
  missing_patient_id: '⚠️ Primero necesito identificar al paciente.\n\nEscribe *hola* para reiniciar.',
};

return [{
  json: {
    ...e,
    _outbound: {
      type: 'text',
      body: msgs[e._error] ?? '⚠️ No pude consultar la disponibilidad en este momento.'
    }
  }
}];

// Preparar prompt para que GROQ identifique el slot que quiere el usuario
const envelope = $input.first().json;
const text     = String(envelope.message?.text ?? '').trim();
const pending  = envelope.session?.pending_context ?? {};
const slots    = Array.isArray(pending.available_slots) ? pending.available_slots : [];
const tz       = envelope.tenant?.timezone ?? 'America/Mexico_City';

const fmt = (iso) => {
  try {
    return new Date(iso).toLocaleString('es-MX', {
      timeZone: tz, weekday: 'long', day: 'numeric',
      month: 'long', hour: '2-digit', minute: '2-digit', hour12: true
    });
  } catch { return iso; }
};

const slotList = slots.map((s, i) => `${i}: ${fmt(s.start)}`).join('\n');

const system =
  'Eres un asistente que identifica horarios médicos. ' +
  'El usuario quiere elegir uno de los siguientes horarios disponibles. ' +
  'Acepta expresiones como "el primero", "mañana", "el martes", "a las 10", etc. ' +
  'Responde ÚNICAMENTE con JSON sin texto adicional:\n' +
  '{"slot_index": N, "confidence": 0.0}\n' +
  'Donde N es el índice (0-based) del horario más probable, o null si no puedes identificarlo con confianza ≥ 0.70.';

const user = `El usuario escribió: "${text}"\n\nHorarios disponibles (índice: fecha):\n${slotList}`;

return [{ json: { ...envelope, _groq_messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } }];

// Parsear respuesta GROQ y resolver slot o señalar fallo
const envelope = $('Build GROQ Prompt — Slot').first().json;
const groqResp = $input.first().json;
const pending  = envelope.session?.pending_context ?? {};
const slots    = Array.isArray(pending.available_slots) ? pending.available_slots : [];

let slotIndex = null;
let confidence = 0;

try {
  const content = String(groqResp?.choices?.[0]?.message?.content ?? '');
  const cleaned = content.replace(/```json|```/g, '').trim();
  const parsed  = JSON.parse(cleaned);
  slotIndex  = parsed?.slot_index ?? null;
  confidence = Number(parsed?.confidence ?? 0);
} catch (_) { /* GROQ no disponible */ }

const idx      = slotIndex !== null ? Number(slotIndex) : -1;
const resolved = (idx >= 0 && idx < slots.length && confidence >= 0.70) ? slots[idx] : null;

return [{
  json: {
    ...envelope,
    _groq_messages: undefined,
    _try_nlp_slot:  undefined,
    _resolved_slot: resolved,
    _slot_confidence: confidence
  }
}];

// Preparar envelope para CF-12 con el slot resuelto por NLP
const e    = $('Resolver NLP — Slot').first().json;
const slot = e._resolved_slot;
if (!slot) throw new Error('NLP slot is null — should not reach here');
const session = e.session ?? {};
return [{
  json: {
    ...e,
    _resolved_slot:   undefined,
    _slot_confidence: undefined,
    _has_cached_slots: undefined,
    _selected_slot:   slot,
    session: {
      ...session,
      current_step:       'confirming',
      pending_slot_start: slot.start ?? null,
      pending_slot_end:   slot.end   ?? null,
    },
    _session_update: {
      current_step:       'confirming',
      pending_slot_start: slot.start ?? null,
      pending_slot_end:   slot.end   ?? null,
      pending_context:    session.pending_context ?? {}
    }
  }
}];

const envelope = $('Preparar ventana').item.json;
const calResp  = $input.first().json;
const pending  = envelope.session?.pending_context ?? {};

let patientName = null;
let serviceName = pending.service_name ?? null;
let serviceDesc = null;
let serviceDuration = pending.service_duration ?? null;
let providerName = pending.provider_name ?? envelope._provider_name ?? null;
let providerSpecialty = pending.provider_specialty ?? envelope._provider_specialty ?? null;

try {
  const rawPat = $('Supabase — GET Patient').first().json;
  const pat    = Array.isArray(rawPat) ? rawPat[0] : rawPat;
  patientName  = pat?.full_name ?? null;
} catch (_) {}

try {
  const rawSvc = $('Supabase — GET Service').first().json;
  const svc    = Array.isArray(rawSvc) ? rawSvc[0] : rawSvc;
  serviceName    = serviceName ?? svc?.name ?? null;
  serviceDesc    = svc?.description ?? null;
  serviceDuration= serviceDuration ?? svc?.duration_minutes ?? null;
} catch (_) {}

return [{
  json: {
    ...envelope,
    _calcom_response: calResp,
    _patient_name:    patientName,
    _service_name:    serviceName,
    _service_desc:    serviceDesc,
    _service_duration: serviceDuration,
    _provider_name: providerName,
    _provider_specialty: providerSpecialty,
  }
}];
